package br.com.marealta.plan;

import br.com.marealta.domain.Money;
import br.com.marealta.domain.Quote;
import java.math.BigDecimal;
import java.util.Map;

/** Convênio com empresas: desconto nas diárias conforme o código da empresa. */
public class CorporatePlan implements RatePlan {
    private static final Map<String, Integer> DISCOUNT_PERCENT_BY_COMPANY = Map.of(
            "TECNOSUL", 12,
            "AGROVALE", 18,
            "FARMAVIDA", 25);

    public String code() { return "CORPORATE"; }

    public Quote quote(BookingRequest r) {
        Integer percent = r.companyCode() == null ? null : DISCOUNT_PERCENT_BY_COMPANY.get(r.companyCode());
        if (percent == null) {
            throw new PlanRuleException("Plano CORPORATE exige um companyCode de empresa conveniada");
        }
        return NightlyPricing.withPercentDiscount(r, percent);
    }

    public BigDecimal refund(BigDecimal amountPaid) { return Money.round(amountPaid); }
}
EOF
cat > WeekendPackagePlan.java <<'EOF'
package br.com.marealta.plan;

import br.com.marealta.domain.Money;
import br.com.marealta.domain.Quote;
import br.com.marealta.domain.RoomType;
import java.math.BigDecimal;
import java.time.DayOfWeek;
import java.util.Map;

/** Pacote de fim de semana: sexta a domingo, preço fechado o ano todo. */
public class WeekendPackagePlan implements RatePlan {
    private static final Map<RoomType, BigDecimal> PRICE = Map.of(
            RoomType.STANDARD, new BigDecimal("520.00"),
            RoomType.DELUXE, new BigDecimal("820.00"),
            RoomType.SUITE, new BigDecimal("1200.00"));

    public String code() { return "WEEKEND_PACKAGE"; }

    public Quote quote(BookingRequest r) {
        if (r.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY || r.nights() != 2) {
            throw new PlanRuleException("O pacote de fim de semana exige entrada na sexta e saída no domingo seguinte");
        }
        return Quote.of(2, Money.round(PRICE.get(r.room().type())), Money.ZERO);
    }

    public BigDecimal refund(BigDecimal amountPaid) { return Money.percent(amountPaid, 50); }
}
EOF
cat > LongStayPlan.java <<'EOF'
package br.com.marealta.plan;

import br.com.marealta.domain.Money;
import br.com.marealta.domain.Quote;
import java.math.BigDecimal;

/** Estadia longa: 7 noites ou mais, 10% de desconto sobre as diárias. */
public class LongStayPlan implements RatePlan {
    static final int MIN_NIGHTS = 7;

    public String code() { return "LONG_STAY"; }

    public Quote quote(BookingRequest r) {
        if (r.nights() < MIN_NIGHTS) {
            throw new PlanRuleException("O plano LONG_STAY exige no mínimo " + MIN_NIGHTS + " noites");
        }
        return NightlyPricing.withPercentDiscount(r, 10);
    }

    public BigDecimal refund(BigDecimal amountPaid) { return Money.round(amountPaid); }
}
EOF
cat > RatePlans.java <<'EOF'
package br.com.marealta.plan;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Registro dos planos de tarifa disponíveis. Para um novo plano, basta incluí-lo aqui. */
public final class RatePlans {
    private static final Map<String, RatePlan> BY_CODE = new LinkedHashMap<>();

    static {
        for (RatePlan p : List.of(new StandardPlan(), new NonRefundablePlan(), new CorporatePlan(),
                new WeekendPackagePlan(), new LongStayPlan())) {
            BY_CODE.put(p.code(), p);
        }
    }

    private RatePlans() {}

    public static Optional<RatePlan> find(String code) {
        return Optional.ofNullable(BY_CODE.get(code));
    }
}
EOF

