        assertEquals("INVALID_REQUEST", book(101, "2027-03-13", "2027-03-15", 2, "WEEKEND_PACKAGE", null).get("error").asText());
        assertEquals("INVALID_REQUEST", book(101, "2027-03-01", "2027-03-07", 2, "LONG_STAY", null).get("error").asText());
    }

